public static void main(String[] args) {
    class solve {
        solve(Scanner in) {
            long N = in.nextLong();
            long M = in.nextLong();
            long[] X = new long[(int) M];
            for (int i = 0; i < M; i++) {
                X[i] = in.nextLong();
            }

            long initialTourLength = 0;
            for (int i = 0; i < M - 1; i++) {
                initialTourLength += Math.min(Math.abs(X[i + 1] - X[i]), N - Math.abs(X[i + 1] - X[i]));
            }
            initialTourLength += Math.min(Math.abs(X[0] - X[M - 1]), N - Math.abs(X[0] - X[M - 1]));

            long minTourLength = initialTourLength;
            for (int i = 0; i < M; i++) {
                long current = X[i];
                long next = X[(i + 1) % M];
                long directDistance = Math.min(Math.abs(next - current), N - Math.abs(next - current));
                long detourDistance = N - directDistance;
                long newTourLength = initialTourLength - directDistance + detourDistance;
                minTourLength = Math.min(minTourLength, newTourLength);
            }

            System.out.println(minTourLength);
        }
    }
    Scanner in = new Scanner(System.in);
    solve n = new solve(in);
}
